import Foundation
let input = try JSONDecoder().decode([String].self, from: FileHandle.standardInput.readDataToEndOfFile())
let rows = input.map { bits -> [String: String] in
    let value = Double(bitPattern: UInt64(bits,radix:16)!)
    return ["bits":bits,"shortestDecimal":String(value),"expected":String(format:"%.8f",locale:Locale(identifier:"en_US_POSIX"),value),"binaryPrintf":String(format:"%.8f",value)]
}
FileHandle.standardOutput.write(try JSONSerialization.data(withJSONObject: rows, options:[.sortedKeys]))
